// ─── LinkedIn Analytics CSV Parser ─────────────────────────────────────────
// El CSV de LinkedIn tiene múltiples secciones separadas por líneas en blanco.
// Secciones típicas:
//   1. Post performance (métricas globales por post)
//   2. Top job function (demografía)
//   3. Top industry
//   4. Top seniority
//   5. Top location
//   6. Top company size
// ────────────────────────────────────────────────────────────────────────────

const binaryData = $binary?.data?.data || $binary?.['data'];
if (!binaryData) throw new Error('No se recibió archivo binario.');

// Decodificar base64 → texto
const csvText = Buffer.from(binaryData, 'base64').toString('utf-8');
const fileName = $('Google Drive — Nuevo Informe').first().json.name || 'desconocido';

// Extraer post_id del nombre del archivo si existe
// Formato LinkedIn: PostAnalytics_NombreAutor_PostID.csv
const postIdMatch = fileName.match(/_([0-9]{15,20})\./);
const postIdFromFile = postIdMatch ? postIdMatch[1] : null;

// Dividir en líneas y detectar secciones
const lines = csvText.split(/\r?\n/);

// Parser de bloque CSV → array de objetos
function parseBlock(rows) {
  if (rows.length < 2) return [];
  const header = rows[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));
  const data = [];
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i].trim();
    if (!row) continue;
    // Simple CSV split (respeta comas dentro de comillas)
    const vals = [];
    let current = '';
    let inQuotes = false;
    for (const ch of row) {
      if (ch === '"') { inQuotes = !inQuotes; continue; }
      if (ch === ',' && !inQuotes) { vals.push(current.trim()); current = ''; continue; }
      current += ch;
    }
    vals.push(current.trim());
    const obj = {};
    header.forEach((h, idx) => { obj[h] = vals[idx] || ''; });
    data.push(obj);
  }
  return data;
}

// Separar bloques por línea en blanco
const blocks = [];
let currentBlock = [];
for (const line of lines) {
  if (line.trim() === '') {
    if (currentBlock.length > 0) { blocks.push(currentBlock); currentBlock = []; }
  } else {
    currentBlock.push(line);
  }
}
if (currentBlock.length > 0) blocks.push(currentBlock);

// Identificar cada bloque por su header
const sections = {};
for (const block of blocks) {
  if (block.length === 0) continue;
  const header = block[0].toLowerCase();
  if (header.includes('content') || header.includes('impressions') || header.includes('views') || header.includes('created')) {
    sections.performance = parseBlock(block);
  } else if (header.includes('job function') || header.includes('función')) {
    sections.job_function = parseBlock(block);
  } else if (header.includes('industry') || header.includes('industria')) {
    sections.industry = parseBlock(block);
  } else if (header.includes('seniority') || header.includes('senioridad')) {
    sections.seniority = parseBlock(block);
  } else if (header.includes('location') || header.includes('ubicación') || header.includes('geo')) {
    sections.location = parseBlock(block);
  } else if (header.includes('company size') || header.includes('tamaño')) {
    sections.company_size = parseBlock(block);
  }
}

// ── Normalizar métricas de performance ──────────────────────────────────────
function num(v) { return parseFloat((v || '0').replace(/,/g, '').replace('%','')) || 0; }
function pct(v) { const n = num(v); return n > 1 ? n / 100 : n; }

const postRows = sections.performance || [];
const posts = postRows.map(row => {
  // LinkedIn usa diferentes nombres de columna según idioma/versión
  const content   = row['Content'] || row['Post'] || row['Contenido'] || '';
  const createdAt = row['Created date'] || row['Date'] || row['Fecha'] || row['Date Created'] || '';
  const postId    = row['Post ID'] || row['Link'] || postIdFromFile || '';
  const postType  = row['Content type'] || row['Type'] || row['Tipo'] || '';

  const impressions   = num(row['Impressions'] || row['Views'] || row['Impresiones'] || row['Vistas'] || '0');
  const uniqueViews   = num(row['Unique views'] || row['Vistas únicas'] || '0');
  const clicks        = num(row['Clicks'] || row['Clics'] || '0');
  const likes         = num(row['Likes'] || row['Me gusta'] || row['Reactions'] || '0');
  const comments      = num(row['Comments'] || row['Comentarios'] || '0');
  const shares        = num(row['Reposts'] || row['Shares'] || row['Compartidos'] || '0');
  const follows       = num(row['Follows'] || row['Seguidores nuevos'] || '0');

  // Click-through rate
  let ctr = pct(row['Click through rate (CTR)'] || row['CTR'] || '0');
  if (ctr === 0 && impressions > 0) ctr = clicks / impressions;

  // Engagement rate: (likes + comments + shares + clicks) / impressions
  const totalEngagements = likes + comments + shares + clicks;
  const er = impressions > 0 ? totalEngagements / impressions : 0;

  return {
    archivo: fileName,
    post_id: postId,
    fecha_publicacion: createdAt,
    tipo: postType,
    contenido_preview: content.substring(0, 200),
    impresiones: impressions,
    vistas_unicas: uniqueViews,
    clics: clicks,
    likes: likes,
    comentarios: comments,
    compartidos: shares,
    nuevos_seguidores: follows,
    ctr: Math.round(ctr * 10000) / 100,  // como porcentaje
    engagement_rate: Math.round(er * 10000) / 100,
    total_interacciones: totalEngagements,
    fecha_importacion: new Date().toISOString().split('T')[0]
  };
});

// ── Normalizar demografía ────────────────────────────────────────────────────
function normalizeDemog(rows, category, postId, archivo) {
  return rows.map(row => {
    const keys = Object.keys(row);
    const labelKey = keys[0];
    const pctKey   = keys.find(k => k.toLowerCase().includes('%') || k.toLowerCase().includes('percentage') || k.toLowerCase().includes('porcentaje')) || keys[1];
    return {
      archivo: archivo,
      post_id: postId,
      categoria: category,
      segmento: row[labelKey] || '',
      porcentaje: num(row[pctKey] || '0'),
      fecha_importacion: new Date().toISOString().split('T')[0]
    };
  });
}

const mainPostId = posts[0]?.post_id || postIdFromFile || fileName;
const demografias = [
  ...normalizeDemog(sections.job_function  || [], 'Función laboral',   mainPostId, fileName),
  ...normalizeDemog(sections.industry      || [], 'Industria',          mainPostId, fileName),
  ...normalizeDemog(sections.seniority     || [], 'Senioridad',         mainPostId, fileName),
  ...normalizeDemog(sections.location      || [], 'Ubicación',          mainPostId, fileName),
  ...normalizeDemog(sections.company_size  || [], 'Tamaño de empresa',  mainPostId, fileName),
];

return [{
  json: {
    posts,
    demografias,
    archivo: fileName,
    total_posts: posts.length,
    total_demog: demografias.length,
    secciones_detectadas: Object.keys(sections)
  }
}];

// Expandir el array de posts como items separados
const data = $input.first().json;
return data.posts.map(post => ({ json: post }));

// Expandir el array de demografías como items separados
const data = $input.first().json;
return data.demografias.map(d => ({ json: d }));

// Consolidar resultados de ambas ramas
const archivo = $('Parsear Informe LinkedIn').first().json.archivo;
const totalPosts = $('Parsear Informe LinkedIn').first().json.total_posts;
const totalDemog = $('Parsear Informe LinkedIn').first().json.total_demog;
const secciones = $('Parsear Informe LinkedIn').first().json.secciones_detectadas;

return [{ json: {
  archivo,
  total_posts: totalPosts,
  total_demog: totalDemog,
  secciones_detectadas: secciones
}}];
